import{_ as a,o as s,c as t,a0 as n}from"./chunks/framework.BmDGRu32.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),r={name:"explanation/architecture.md"};function i(o,e,c,l,p,d){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Three layers, strictly ordered by authority:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        ┌────────── evented layer ──────────┐</span></span>
<span class="line"><span>agents  │  ops: write/rename/claim/intent/… │</span></span>
<span class="line"><span>        │  virtual workspaces (ws = pointer) │</span></span>
<span class="line"><span>        │  bus: repo.&lt;id&gt;.{ops,claims,…}     │</span></span>
<span class="line"><span>        └──────┬─────────────────┬───────────┘</span></span>
<span class="line"><span>               │ append          │ append (offline)</span></span>
<span class="line"><span>        refs/sturn/wal/* ── git ODB ── refs/sturn/ws/*</span></span>
<span class="line"><span>               │</span></span>
<span class="line"><span>        normal git push/fetch → GitHub — free, signed, ordinary</span></span></code></pre></div><h2 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to &quot;Invariants&quot;">​</a></h2><ol><li><strong>The WAL is the state.</strong> Anything derivable from <code>refs/sturn/wal/*</code> is a cache (bus cursors, materialized views).</li><li><strong>Merges stay git&#39;s.</strong> Ops never encode merge semantics — claims prevent collisions; <code>snap</code> squashes into ordinary commits.</li><li><strong>Coordination before work.</strong> Claims publish <em>before</em> edits. Discovering a conflict at merge is the failure mode git taught us.</li></ol><h2 id="what-each-piece-owes" tabindex="-1">What each piece owes <a class="header-anchor" href="#what-each-piece-owes" aria-label="Permalink to &quot;What each piece owes&quot;">​</a></h2><ul><li><code>refs/sturn/wal/&lt;ws&gt;</code> — source of truth, replicates for free</li><li>daemon + bus — latency reduction only; optional</li><li><code>refs/sturn/ws/&lt;name&gt;</code> — workspace namespaces; hydration opt-in</li><li><code>snap</code> — the bridge back to ordinary git history</li></ul><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><p>Sturn owns <strong>ephemeral coordination</strong> — live claims, ops, topics, asks over VCS state. Neighbors own theirs:</p><ul><li><strong>myco</strong> — durable work memory (the <code>project/</code> ledger); sturn coordinates the moment, myco remembers the intent.</li><li><strong>kuda</strong> — code memory; <code>.kuda/</code> cards are that repo&#39;s concern.</li><li><strong>tamias</strong> — distribution; the <code>sturn</code> command is a tamias pack, releases run through <code>tarsi-serve</code>.</li><li><strong>peregrin/hypha</strong> — orchestration substrate; sturn is the coordination layer agents call directly.</li></ul><h2 id="where-it-sits" tabindex="-1">Where it sits <a class="header-anchor" href="#where-it-sits" aria-label="Permalink to &quot;Where it sits&quot;">​</a></h2><p>In the org&#39;s layering — <strong>tamias</strong> (package &amp; content manager) → <strong>engines</strong> (myco records, kuda code maps, mimus proofs, sepia sessions, hypha substrate, tarsi releases, cicada schedules, cypera docs, scarab config) → <strong>orchestration</strong> (peregrin campaigns) → <strong>surfaces</strong> (pavo views, MCP fronts, agent harnesses).</p><p>Sturn is an <strong>engine</strong> — the coordination substrate every agent calls directly, below orchestration. It isn&#39;t orchestrated itself: agents <code>claim</code>/<code>write</code>/<code>snap</code> against the WAL, the daemon only fans events onto topics, and peregrin campaigns can consume sturn ops as events without sturn knowing they exist.</p>`,13)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
